//MUX state

reg     InMUX;

always  @(
            ID0EnCNTup or
            ID1EnCNTup or
            ID2EnCNTup or
            ID3EnCNTup or
            ID4EnCNTup or
            ID5EnCNTup or
            ID6EnCNTup or
            ID7EnCNTup or
            ID8EnCNTup or
            ID9EnCNTup or
            ID10EnCNTup or
            ID11EnCNTup or
            ID12EnCNTup or
            ID13EnCNTup or
            ID14EnCNTup or
            ID15EnCNTup or
            AVALID  
        )
begin
    if(AVALID & (
            ID0EnCNTup |
            ID1EnCNTup |
            ID2EnCNTup |
            ID3EnCNTup |
            ID4EnCNTup |
            ID5EnCNTup |
            ID6EnCNTup |
            ID7EnCNTup |
            ID8EnCNTup |
            ID9EnCNTup |
            ID10EnCNTup |
            ID11EnCNTup |
            ID12EnCNTup |
            ID13EnCNTup |
            ID14EnCNTup |
            ID15EnCNTup  
       ))
        InMUX <= 1'b1;
    else
        InMUX <= 1'b0;
end

//MUX 
reg     [SLAVE_WID-1:0] SIDSlaveBuffer;
//Ver 1.9
reg     SIDSlaveFull;
wire    EnData;
//Ver 1.9
assign  CtlData2writech[SLAVE_WID]     = SIDSlaveFull ? 1'b0 : InMUX; 
assign  CtlData2writech[SLAVE_WID-1:0] = SIDSlaveBuffer;

assign  CtlData2datach[SLAVE_WID-1:0]  = WIDSlaveBuffer[SLAVE_WID-1:0];
assign  CtlData2datach[SLAVE_WID]      = EnData;

reg [2:0]StateWID;
reg [2:0]NxStateWID;


parameter WR_WID = 0,
          HOLD_WID = 1,
          WAIT_WID = 2;

assign  EnData = StateWID[WR_WID];
always @(posedge ACLK or negedge ARESETn)
begin
    if(!ARESETn)
    begin
        StateWID[WR_WID]    <= 1'b1;
        StateWID[HOLD_WID]  <= 1'b0;
        StateWID[WAIT_WID]  <= 1'b0;
    end
    else
    begin
        StateWID <= NxStateWID;
    end
end

//Ver 1.6 Wdata permit control modified
always @(
            CNTdn_1p or
            EnWIDSlaveCnt or
            WREADY or WVALID or WLAST or
            WID or SID or StateWID
        )
begin
    NxStateWID <= 0;
    case(1'b1)
        
        StateWID[WR_WID]:
            if(WREADY & WVALID & WLAST)
                NxStateWID[HOLD_WID]<= 1'b1;
            else
                NxStateWID[WR_WID]  <= 1'b1;

        StateWID[HOLD_WID]:
            if(CNTdn_1p & EnWIDSlaveCnt)
                NxStateWID[WR_WID]  <= 1'b1;
            else if(CNTdn_1p & !EnWIDSlaveCnt)
                NxStateWID[WAIT_WID]  <= 1'b1;
            else
                NxStateWID[HOLD_WID]<= 1'b1;

        StateWID[WAIT_WID]:
            if(EnWIDSlaveCnt)
                NxStateWID[WR_WID]  <= 1'b1;
            else if(!EnWIDSlaveCnt && (SID==WID))
                NxStateWID[WR_WID]  <= 1'b1;
            else
                NxStateWID[WAIT_WID]  <= 1'b1;

        default:
                NxStateWID[WR_WID]  <= 1'b1;
    endcase
end

always  @(
            ID0SlaveBuffer or
            ID1SlaveBuffer or
            ID2SlaveBuffer or
            ID3SlaveBuffer or
            ID4SlaveBuffer or
            ID5SlaveBuffer or
            ID6SlaveBuffer or
            ID7SlaveBuffer or
            ID8SlaveBuffer or
            ID9SlaveBuffer or
            ID10SlaveBuffer or
            ID11SlaveBuffer or
            ID12SlaveBuffer or
            ID13SlaveBuffer or
            ID14SlaveBuffer or
            ID15SlaveBuffer or
            SID
        )
begin
    case(SID)
    //synopsys parallel_case full_case
        4'd0:   SIDSlaveBuffer = ID0SlaveBuffer;
        4'd1:   SIDSlaveBuffer = ID1SlaveBuffer;
        4'd2:   SIDSlaveBuffer = ID2SlaveBuffer;
        4'd3:   SIDSlaveBuffer = ID3SlaveBuffer;
        4'd4:   SIDSlaveBuffer = ID4SlaveBuffer;
        4'd5:   SIDSlaveBuffer = ID5SlaveBuffer;
        4'd6:   SIDSlaveBuffer = ID6SlaveBuffer;
        4'd7:   SIDSlaveBuffer = ID7SlaveBuffer;
        4'd8:   SIDSlaveBuffer = ID8SlaveBuffer;
        4'd9:   SIDSlaveBuffer = ID9SlaveBuffer;
        4'd10:   SIDSlaveBuffer = ID10SlaveBuffer;
        4'd11:   SIDSlaveBuffer = ID11SlaveBuffer;
        4'd12:   SIDSlaveBuffer = ID12SlaveBuffer;
        4'd13:   SIDSlaveBuffer = ID13SlaveBuffer;
        4'd14:   SIDSlaveBuffer = ID14SlaveBuffer;
        4'd15:   SIDSlaveBuffer = ID15SlaveBuffer;
    endcase
end

//Ver 1.9
always  @(
            ID0SlaveCntFull or
            ID1SlaveCntFull or
            ID2SlaveCntFull or
            ID3SlaveCntFull or
            ID4SlaveCntFull or
            ID5SlaveCntFull or
            ID6SlaveCntFull or
            ID7SlaveCntFull or
            ID8SlaveCntFull or
            ID9SlaveCntFull or
