            ID11SlaveCntFull or
            ID12SlaveCntFull or
            ID13SlaveCntFull or
            ID14SlaveCntFull or
            ID15SlaveCntFull or
            SID
        )
begin
    case(SID)
    //synopsys parallel_case full_case
        4'd0:   SIDSlaveFull = ID0SlaveCntFull;
        4'd1:   SIDSlaveFull = ID1SlaveCntFull;
        4'd2:   SIDSlaveFull = ID2SlaveCntFull;
        4'd3:   SIDSlaveFull = ID3SlaveCntFull;
        4'd4:   SIDSlaveFull = ID4SlaveCntFull;
        4'd5:   SIDSlaveFull = ID5SlaveCntFull;
        4'd6:   SIDSlaveFull = ID6SlaveCntFull;
        4'd7:   SIDSlaveFull = ID7SlaveCntFull;
        4'd8:   SIDSlaveFull = ID8SlaveCntFull;
        4'd9:   SIDSlaveFull = ID9SlaveCntFull;
        4'd10:   SIDSlaveFull = ID10SlaveCntFull;
        4'd11:   SIDSlaveFull = ID11SlaveCntFull;
        4'd12:   SIDSlaveFull = ID12SlaveCntFull;
        4'd13:   SIDSlaveFull = ID13SlaveCntFull;
        4'd14:   SIDSlaveFull = ID14SlaveCntFull;
        4'd15:   SIDSlaveFull = ID15SlaveCntFull;
    endcase
end


